INSERT INTO tcm_syndrome (disease_id, syndrome_name, syndrome_type, main_symptoms, secondary_symptoms, tongue_pulse, pathogenesis, treatment_principle, recommended_formula, modified_formula, acupoints, dietary_advice, daily_regimen, prognosis, differential_diagnosis, remark, sort_order, status, created_at, updated_at) VALUES
	 (1,'风寒束表证','外感六淫','恶寒发热，头痛身痛，无汗，鼻塞流清涕','喷嚏，咳嗽，痰白清稀，骨节酸痛','舌淡苔薄白，脉浮紧','风寒之邪侵袭肌表，正邪抗争','辛温解表','麻黄汤','表虚自汗者用桂枝汤；兼湿者用羌活胜湿汤','风池、风门、肺俞、列缺','宜食辛温发散食物，忌生冷寒凉','注意保暖，避免风寒侵袭','预后良好','与风热表证鉴别：风热发热重恶寒轻，咽喉红肿',NULL,1,1,'2026-03-13 13:52:08','2026-03-13 13:52:08'),
	 (1,'风热犯表证','外感六淫','发热重恶寒轻，咽喉红肿疼痛，头痛口渴','咳嗽痰黄，鼻塞流浊涕，汗出','舌红苔薄黄，脉浮数','风热之邪侵袭肺卫','辛凉解表','银翘散','热盛者用桑菊饮；兼湿者加藿香、佩兰','大椎、曲池、合谷、外关','宜食清淡清凉食物，忌辛辣油腻','多饮水，保持室内通风','预后良好','与风寒表证鉴别：风寒恶寒重发热轻，流清涕',NULL,2,1,'2026-03-13 13:52:08','2026-03-13 13:52:08'),
	 (1,'暑湿袭表证','外感六淫','发热汗出不解，头身困重，胸闷脘痞','口渴不欲饮，小便短赤，大便溏泄','舌红苔黄腻，脉濡数','暑湿之邪侵袭肌表，困阻中焦','清暑化湿','新加香薷饮','湿重者用三仁汤；热重者用白虎加苍术汤','合谷、中脘、足三里、阴陵泉','宜食清淡祛湿食物，忌油腻辛辣','注意防暑降温，保持室内凉爽','预后良好','与湿热证鉴别：湿热病位偏里，病程较长',NULL,3,1,'2026-03-13 13:52:08','2026-03-13 13:52:08'),
	 (2,'燥邪犯肺证','外感六淫','干咳无痰或痰少黏稠难咳，咽干口燥','鼻干，唇干，皮肤干燥，尿少便干','舌红苔少而干，脉细数','燥邪伤肺，耗伤肺津','清燥润肺','桑杏汤','燥热甚者用清燥救肺汤；燥寒者用杏苏散','肺俞、中府、尺泽、太溪','宜食润肺生津食物，忌辛辣烟酒','保持室内湿度，多饮水','预后良好','与阴虚肺燥证鉴别：阴虚有内热病史，病程长',NULL,4,1,'2026-03-13 13:52:08','2026-03-13 13:52:08'),
	 (2,'寒湿困脾证','外感六淫','脘腹胀满，恶心呕吐，口黏不渴','肢体困重，头身困重，大便溏薄','舌淡胖苔白腻，脉濡缓','寒湿之邪困阻中焦，脾失健运','温中化湿','藿香正气散','湿重者用胃苓汤；寒甚者用理中汤','中脘、脾俞、阴陵泉、足三里','宜食温燥化湿食物，忌生冷油腻','注意保暖，避免潮湿环境','预后良好','与湿热困脾证鉴别：湿热口苦，苔黄腻',NULL,5,1,'2026-03-13 13:52:08','2026-03-13 13:52:08'),
	 (2,'湿热蕴结证','外感六淫','身热不扬，汗出不解，口渴不欲饮','胸脘痞闷，纳呆呕恶，小便短赤，大便黏滞','舌红苔黄腻，脉濡数','湿热之邪蕴结，气机不畅','清热利湿','三仁汤','热重者用连朴饮；湿重者用藿朴夏苓汤','中脘、阴陵泉、丰隆、曲池','宜食清热利湿食物，忌油腻甜食','保持清洁干燥，避免潮湿','预后良好','与寒湿证鉴别：寒湿恶寒，口不渴',NULL,6,1,'2026-03-13 13:52:08','2026-03-13 13:52:08'),
	 (31,'气虚证','气血津液','神疲乏力，少气懒言，面色萎黄','自汗，易感冒，头晕目眩，纳少','舌淡苔白，脉弱无力','元气不足，脏腑功能减退','补气益气','四君子汤','肺气虚者加黄芪；脾气虚者用香砂六君子汤','气海、足三里、脾俞、肺俞','宜食补气食物，忌破气耗气','避免过度劳累，适当休息','预后较好','与阳虚证鉴别：阳虚有畏寒肢冷',NULL,7,1,'2026-03-13 13:52:08','2026-03-13 13:52:08'),
	 (31,'血虚证','气血津液','面色苍白或萎黄，头晕眼花，心悸失眠','手足麻木，爪甲不荣，妇女月经量少色淡','舌淡苔白，脉细无力','血液亏虚，脏腑组织失养','补血养血','四物汤','兼气虚用八珍汤；兼阴虚用归芍地黄汤','血海、三阴交、心俞、膈俞','宜食补血食物，忌生冷寒凉','注意休息，避免过度劳累','预后较好','与阴虚证鉴别：阴虚有虚热征象',NULL,8,1,'2026-03-13 13:52:08','2026-03-13 13:52:08'),
	 (31,'气血两虚证','气血津液','面色苍白，气短懒言，头晕眼花','心悸失眠，自汗盗汗，肢体麻木','舌淡苔白，脉细弱','气血亏虚，脏腑失养','气血双补','八珍汤','偏气虚用十全大补汤；偏血虚用人参养荣汤','气海、血海、足三里、三阴交','宜食气血双补食物，忌破气耗血','劳逸结合，营养均衡','预后较好','与单纯气虚或血虚鉴别：本证气虚血虚并见',NULL,9,1,'2026-03-13 13:52:08','2026-03-13 13:52:08'),
	 (31,'阴虚证','气血津液','五心烦热，潮热盗汗，口燥咽干','颧红，形体消瘦，小便短少，大便干结','舌红少津，脉细数','阴液亏损，虚热内生','滋阴清热','六味地黄丸','肺阴虚用百合固金汤；胃阴虚用沙参麦冬汤','三阴交、太溪、复溜、照海','宜食滋阴润燥食物，忌辛辣燥热','避免熬夜，保持情绪稳定','预后较好','与血虚证鉴别：血虚无虚热征象',NULL,10,1,'2026-03-13 13:52:08','2026-03-13 13:52:08');
INSERT INTO tcm_syndrome (disease_id, syndrome_name, syndrome_type, main_symptoms, secondary_symptoms, tongue_pulse, pathogenesis, treatment_principle, recommended_formula, modified_formula, acupoints, dietary_advice, daily_regimen, prognosis, differential_diagnosis, remark, sort_order, status, created_at, updated_at) VALUES
	 (31,'阳虚证','气血津液','畏寒肢冷，面色苍白，精神萎靡','口淡不渴，小便清长，大便溏薄','舌淡胖苔白滑，脉沉弱','阳气不足，温煦失职','温补阳气','金匮肾气丸','肾阳虚用右归丸；脾阳虚用理中汤','关元、气海、命门、足三里','宜食温补食物，忌生冷寒凉','注意保暖，适当运动','预后较好','与气虚证鉴别：阳虚有畏寒肢冷',NULL,11,1,'2026-03-13 13:52:08','2026-03-13 13:52:08'),
	 (31,'气滞证','气血津液','胸胁胀满，情志抑郁，善太息','妇女乳房胀痛，月经不调，痛经','舌淡红苔薄白，脉弦','气机郁滞，运行不畅','行气解郁','柴胡疏肝散','肝气郁结用逍遥散；脾胃气滞用越鞠丸','太冲、膻中、内关、期门','宜食疏肝理气食物，忌郁怒','调节情志，保持心情舒畅','预后较好','与血瘀证鉴别：血瘀有固定刺痛',NULL,12,1,'2026-03-13 13:52:08','2026-03-13 13:52:08'),
	 (31,'血瘀证','气血津液','痛如针刺，痛处固定拒按','面色晦暗，口唇紫暗，舌质紫暗有瘀点','舌紫暗或有瘀斑，脉涩','血液瘀滞，运行不畅','活血化瘀','血府逐瘀汤','瘀血阻络用身痛逐瘀汤；瘀阻胸中用丹参饮','血海、膈俞、三阴交、合谷','宜食活血化瘀食物，忌寒凉','适当活动，促进血液循环','预后一般，易反复','与气滞证鉴别：气滞为胀痛，游走不定',NULL,13,1,'2026-03-13 13:52:08','2026-03-13 13:52:08'),
	 (31,'痰湿证','气血津液','形体肥胖，身重困倦，胸闷脘痞','咳嗽痰多，恶心呕吐，口黏不渴','舌淡胖苔白腻，脉滑','痰湿内阻，气机不畅','燥湿化痰','二陈汤','痰热扰心用黄连温胆汤；痰湿中阻用平胃散','中脘、丰隆、脾俞、足三里','宜食化痰祛湿食物，忌肥甘厚腻','控制饮食，适当运动','预后一般，易反复','与湿热证鉴别：湿热有热象，苔黄腻',NULL,14,1,'2026-03-13 13:52:08','2026-03-13 13:52:08'),
	 (12,'心气虚证','脏腑','心悸气短，活动后加重，神疲乏力','面色苍白，自汗，易惊','舌淡苔白，脉弱','心气不足，鼓动无力','补益心气','养心汤','兼血虚用归脾汤；兼阳虚用保元汤','心俞、巨阙、神门、内关','宜食补气养心食物，忌耗气','避免过度劳累，保持情绪稳定','预后较好','与心阴虚证鉴别：心阴虚有心烦失眠',NULL,15,1,'2026-03-13 13:52:08','2026-03-13 13:52:08'),
	 (12,'心血虚证','脏腑','心悸怔忡，失眠多梦，健忘','面色萎黄，头晕目眩，肢体麻木','舌淡苔白，脉细弱','血液亏虚，心失所养','补血养心','归脾汤','兼阴虚用天王补心丹；兼气虚用八珍汤','心俞、巨阙、三阴交、血海','宜食补血养心食物','保证充足睡眠，劳逸结合','预后较好','与心气虚证鉴别：心血虚有头晕眼花',NULL,16,1,'2026-03-13 13:52:08','2026-03-13 13:52:08'),
	 (12,'心阴虚证','脏腑','心悸怔忡，失眠多梦，五心烦热','盗汗，口燥咽干，颧红','舌红少津，脉细数','心阴不足，虚热内生','滋阴降火','天王补心丹','虚热甚者用朱砂安神丸；兼火旺用黄连阿胶汤','心俞、巨阙、太溪、神门','宜食滋阴清心食物','避免熬夜，保持情绪稳定','预后较好','与心血虚证鉴别：心阴虚有虚热征象',NULL,17,1,'2026-03-13 13:52:08','2026-03-13 13:52:08'),
	 (12,'心阳虚证','脏腑','心悸气短，胸痛彻背，畏寒肢冷','面色苍白，自汗，神疲乏力','舌淡胖苔白滑，脉沉弱','心阳不足，温煦失职','温补心阳','桂枝甘草龙骨牡蛎汤','寒甚用参附汤；兼血瘀用血府逐瘀汤','心俞、巨阙、关元、内关','宜食温补心阳食物','注意保暖，避免寒冷刺激','预后一般','与心气虚证鉴别：心阳虚有畏寒肢冷',NULL,18,1,'2026-03-13 13:52:08','2026-03-13 13:52:08'),
	 (2,'肺气虚证','脏腑','咳喘无力，气短声低，自汗畏风','易感冒，面色苍白，神疲乏力','舌淡苔白，脉弱','肺气不足，宣降失常','补益肺气','补肺汤','兼痰湿用二陈汤；兼阴虚用生脉散','肺俞、中府、足三里、气海','宜食补肺益气食物','避免烟酒，预防感冒','预后较好','与肺阴虚证鉴别：肺阴虚有干咳盗汗',NULL,19,1,'2026-03-13 13:52:08','2026-03-13 13:52:08'),
	 (2,'肺阴虚证','脏腑','干咳无痰或痰少黏稠，口燥咽干','手足心热，颧红，盗汗','舌红少津，脉细数','肺阴不足，虚热内生','滋阴润肺','百合固金汤','燥热甚者用清燥救肺汤；咯血者用百合固金汤加减','肺俞、尺泽、太溪、孔最','宜食滋阴润肺食物','避免烟酒，保持室内湿度','预后一般','与肺气虚证鉴别：肺阴虚有虚热征象',NULL,20,1,'2026-03-13 13:52:08','2026-03-13 13:52:08');
INSERT INTO tcm_syndrome (disease_id, syndrome_name, syndrome_type, main_symptoms, secondary_symptoms, tongue_pulse, pathogenesis, treatment_principle, recommended_formula, modified_formula, acupoints, dietary_advice, daily_regimen, prognosis, differential_diagnosis, remark, sort_order, status, created_at, updated_at) VALUES
	 (4,'脾气虚证','脏腑','食少纳呆，腹胀便溏，神疲乏力','少气懒言，面色萎黄，肢体倦怠','舌淡苔白，脉弱','脾气不足，运化失职','健脾益气','四君子汤','兼湿用香砂六君子汤；兼寒用理中汤','脾俞、足三里、中脘、太白','宜食健脾益气食物','饮食规律，避免暴饮暴食','预后较好','与脾阳虚证鉴别：脾阳虚有腹痛喜温',NULL,21,1,'2026-03-13 13:52:08','2026-03-13 13:52:08'),
	 (4,'脾阳虚证','脏腑','脘腹冷痛，喜温喜按，食少腹胀','大便溏薄，畏寒肢冷，口淡不渴','舌淡胖苔白滑，脉沉迟','脾阳不足，温煦失职','温中健脾','理中汤','寒甚用附子理中丸；兼湿用实脾饮','脾俞、足三里、关元、中脘','宜食温补脾阳食物','注意腹部保暖','预后一般','与脾气虚证鉴别：脾阳虚有寒象',NULL,22,1,'2026-03-13 13:52:08','2026-03-13 13:52:08'),
	 (4,'胃阴虚证','脏腑','胃脘隐痛，饥不欲食，口燥咽干','大便干结，干呕呃逆','舌红少津，脉细数','胃阴不足，濡养失职','养阴和胃','益胃汤','兼热甚用沙参麦冬汤；兼气虚用生脉散','中脘、足三里、内庭、内关','宜食养阴和胃食物','饮食清淡，避免辛辣刺激','预后较好','与胃热证鉴别：胃热有口渴便秘',NULL,23,1,'2026-03-13 13:52:08','2026-03-13 13:52:08'),
	 (32,'肝气郁结证','脏腑','胸胁胀满，情志抑郁，善太息','乳房胀痛，月经不调，痛经','舌淡红苔薄白，脉弦','肝气郁滞，疏泄失常','疏肝解郁','柴胡疏肝散','化火用丹栀逍遥散；兼痰湿用温胆汤','太冲、期门、膻中、内关','宜食疏肝理气食物','调节情志，保持心情舒畅','预后较好','与肝火上炎证鉴别：肝火有面红目赤',NULL,24,1,'2026-03-13 13:52:08','2026-03-13 13:52:08'),
	 (32,'肝火上炎证','脏腑','头痛眩晕，面红目赤，口苦咽干','急躁易怒，耳鸣如潮，胁肋灼痛','舌红苔黄，脉弦数','肝火上攻，火热炽盛','清肝泻火','龙胆泻肝汤','兼阴虚用天麻钩藤饮；头痛甚用天麻钩藤饮','太冲、行间、风池、太阳','宜食清肝泻火食物','保持情绪稳定','预后较好','与肝气郁结证鉴别：肝火有火热征象',NULL,25,1,'2026-03-13 13:52:08','2026-03-13 13:52:08'),
	 (32,'肝阴虚证','脏腑','头晕目眩，两目干涩，视物模糊','五心烦热，潮热盗汗，胁肋隐痛','舌红少津，脉弦细数','肝阴不足，虚热内生','滋养肝阴','一贯煎','兼肾阴不足用杞菊地黄丸；兼火旺用知柏地黄丸','太冲、三阴交、肝俞、太溪','宜食滋养肝阴食物','避免熬夜，注意用眼卫生','预后较好','与肝火上炎证鉴别：肝阴虚无实热征象',NULL,26,1,'2026-03-13 13:52:08','2026-03-13 13:52:08'),
	 (33,'肾阴虚证','脏腑','腰膝酸软，头晕耳鸣，五心烦热','潮热盗汗，遗精早泄，口燥咽干','舌红少津，脉细数','肾阴不足，虚热内生','滋阴补肾','六味地黄丸','相火妄动用知柏地黄丸；精关不固用左归丸','肾俞、太溪、三阴交、照海','宜食滋阴补肾食物','节制房事，避免过度劳累','预后较好','与肾阳虚证鉴别：肾阳虚有畏寒肢冷',NULL,27,1,'2026-03-13 13:52:08','2026-03-13 13:52:08'),
	 (33,'肾阳虚证','脏腑','腰膝酸冷，畏寒肢冷，精神萎靡','小便清长，夜尿频多，男子阳痿早泄','舌淡胖苔白滑，脉沉弱','肾阳不足，温煦失职','温补肾阳','金匮肾气丸','命门火衰用右归丸；阳痿甚用赞育丹','命门、关元、肾俞、气海','宜食温补肾阳食物','注意保暖，避免房事过度','预后一般','与肾阴虚证鉴别：肾阳虚有寒象',NULL,28,1,'2026-03-13 13:52:08','2026-03-13 13:52:08'),
	 (4,'胃寒证','脏腑','胃脘冷痛，得温痛减，遇寒加重','呕吐清水，口淡不渴，畏寒喜暖','舌淡苔白，脉沉迟','寒邪犯胃，中阳被遏','温胃散寒','良附丸','寒甚用附子理中丸；兼气滞用厚朴温中汤','中脘、足三里、内关、梁丘','宜食温胃散寒食物','注意胃部保暖','预后较好','与胃热证鉴别：胃热有口苦喜冷',NULL,29,1,'2026-03-13 13:52:08','2026-03-13 13:52:08'),
	 (4,'胃热证','脏腑','胃脘灼痛，口渴喜冷饮','牙龈肿痛，口臭，便秘尿黄','舌红苔黄，脉滑数','胃火炽盛，腐熟水谷失常','清胃泻火','清胃散','热甚用泻心汤；便秘用大黄黄连泻心汤','中脘、内庭、合谷、内关','宜食清胃泻火食物','忌辛辣烟酒','预后较好','与胃寒证鉴别：胃寒有口淡喜温',NULL,30,1,'2026-03-13 13:52:08','2026-03-13 13:52:08');
INSERT INTO tcm_syndrome (disease_id, syndrome_name, syndrome_type, main_symptoms, secondary_symptoms, tongue_pulse, pathogenesis, treatment_principle, recommended_formula, modified_formula, acupoints, dietary_advice, daily_regimen, prognosis, differential_diagnosis, remark, sort_order, status, created_at, updated_at) VALUES
	 (6,'大肠湿热证','脏腑','腹痛腹泻，里急后重，大便脓血','肛门灼热，小便短赤','舌红苔黄腻，脉滑数','湿热蕴结大肠，传导失职','清肠化湿','葛根芩连汤','湿热甚用白头翁汤；气滞用木香槟榔丸','天枢、上巨虚、阴陵泉、曲池','宜食清肠化湿食物','注意饮食卫生','预后较好','与大肠虚寒证鉴别：虚寒有便溏清稀',NULL,31,1,'2026-03-13 13:52:08','2026-03-13 13:52:08'),
	 (23,'膀胱湿热证','脏腑','尿频尿急，尿涩而痛，小便短赤','或血尿，或尿有砂石，伴发热','舌红苔黄腻，脉滑数','湿热蕴结膀胱，气化不利','清热利湿通淋','八正散','血淋用小蓟饮子；石淋用石韦散','中极、膀胱俞、三阴交、阴陵泉','宜食清热利湿食物','多饮水，保持外阴清洁','预后较好','与膀胱虚寒证鉴别：虚寒有尿清长',NULL,32,1,'2026-03-13 13:52:08','2026-03-13 13:52:08');
